-- Retailers are global (not owned by a partner). partner_id becomes optional, and the retailers of the
-- local database are added to this one. Rows already here (same name within about 30 m) are skipped,
-- so nothing existing is changed. Dues start at 0 and the creating SR is not carried over (ids differ per server).
USE `happybasic`;
SET time_zone = '+06:00';

DROP TABLE IF EXISTS `tmp_retailer_import`;
CREATE TABLE `tmp_retailer_import` (`name` VARCHAR(150) NOT NULL, `phone` VARCHAR(30) NULL, `address` VARCHAR(255) NOT NULL, `lat` DECIMAL(10, 7) NOT NULL, `lng` DECIMAL(10, 7) NOT NULL, `created_at` TIMESTAMP NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;













SELECT NULL, NULL, t.`name`, t.`phone`, t.`address`, t.`lat`, t.`lng`, 0, 'active', t.`created_at` FROM `tmp_retailer_import` t
WHERE NOT EXISTS (SELECT 1 FROM `retailers` r WHERE r.`name` = t.`name` AND ABS(r.`lat` - t.`lat`) < 0.0003 AND ABS(r.`lng` - t.`lng`) < 0.0003);

DROP TABLE `tmp_retailer_import`;
